#!/usr/bin/env perl
# ABOUTME: Test systematic loop-carried dependency tracking with phi nodes
# ABOUTME: Validates that all loop-modified variables get phi nodes automatically

use 5.42.0;
use Test2::V0;
use FindBin qw($RealBin);
use experimental qw(defer);
defer { done_testing() }

use lib "$RealBin/../../lib";
use Chalk::Parser;
use Chalk::Grammar;
use Chalk::IR::Builder;

# Load the chalk.bnf grammar
open my $grammar_fh, "<:utf8", "$RealBin/../../grammar/chalk.bnf" or die $!;
my $bnf_content = do { local $/; <$grammar_fh> };
close $grammar_fh;

my $chalk_grammar = Chalk::Grammar->build_from_bnf($bnf_content, "Program");

subtest 'Single modified variable generates loop phi' => sub {
    my $code = q{
        my $i = 0;
        while ($i < 10) {
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $result = $parser->parse_string($code);
    ok $result, 'Parsed successfully';

    # Get the IR graph
    my $graph = $result->graph;
    ok $graph, 'Graph exists';

    # Find Loop node
    my @loop_nodes = grep { $_->op eq 'Loop' } $graph->nodes->@*;
    is scalar(@loop_nodes), 1, 'One Loop node exists';

    # Find Phi nodes that have Loop as control
    my $loop_id = $loop_nodes[0]->id;
    my @loop_phis = grep {
        $_->op eq 'Phi' &&
        $_->inputs->[0] eq $loop_id
    } $graph->nodes->@*;

    # Should have at least one phi for $i
    cmp_ok scalar(@loop_phis), '>=', 1, 'At least one loop phi node for modified variable';

    # Verify phi structure: [loop_control, initial_value, loop_value]
    my $phi = $loop_phis[0];
    is $phi->inputs->[0], $loop_id, 'Phi control is Loop node';
    ok defined($phi->inputs->[1]), 'Phi has initial value';

    # Check for backedge (lazy phi pattern - may be added later)
    # But phi should exist even if backedge not yet connected
    ok $phi, 'Loop phi node created systematically';
};

subtest 'Multiple modified variables generate multiple loop phis' => sub {
    my $code = q{
        my $sum = 0;
        my $i = 0;
        while ($i < 10) {
            $sum = $sum + $i;
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $result = $parser->parse_string($code);
    ok $result, 'Parsed successfully';

    my $graph = $result->graph;

    # Find Loop node
    my @loop_nodes = grep { $_->op eq 'Loop' } $graph->nodes->@*;
    my $loop_id = $loop_nodes[0]->id;

    # Find all loop phi nodes
    my @loop_phis = grep {
        $_->op eq 'Phi' &&
        $_->inputs->[0] eq $loop_id
    } $graph->nodes->@*;

    # Should have phi nodes for both $sum and $i
    cmp_ok scalar(@loop_phis), '>=', 2, 'Loop phi nodes for all modified variables ($sum and $i)';
};

subtest 'Unmodified variables do not generate loop phis' => sub {
    my $code = q{
        my $limit = 10;
        my $i = 0;
        while ($i < $limit) {
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $result = $parser->parse_string($code);
    ok $result, 'Parsed successfully';

    my $graph = $result->graph;

    # Find Loop node
    my @loop_nodes = grep { $_->op eq 'Loop' } $graph->nodes->@*;
    my $loop_id = $loop_nodes[0]->id;

    # Find all loop phi nodes
    my @loop_phis = grep {
        $_->op eq 'Phi' &&
        $_->inputs->[0] eq $loop_id
    } $graph->nodes->@*;

    # Should have phi only for $i, not for $limit
    # $limit is not modified in the loop
    is scalar(@loop_phis), 1, 'Only modified variables get phi nodes';
};

subtest 'Nested loops generate separate phi nodes' => sub {
    my $code = q{
        my $i = 0;
        while ($i < 5) {
            my $j = 0;
            while ($j < 3) {
                $j = $j + 1;
            }
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $result = $parser->parse_string($code);
    ok $result, 'Parsed successfully';

    my $graph = $result->graph;

    # Find all Loop nodes
    my @loop_nodes = grep { $_->op eq 'Loop' } $graph->nodes->@*;
    is scalar(@loop_nodes), 2, 'Two nested loops';

    # Each loop should have its own phi nodes
    for my $loop (@loop_nodes) {
        my @phis = grep {
            $_->op eq 'Phi' &&
            $_->inputs->[0] eq $loop->id
        } $graph->nodes->@*;

        cmp_ok scalar(@phis), '>=', 1, 'Each loop has its own phi nodes';
    }
};

subtest 'Loop phi backedge is properly connected' => sub {
    my $code = q{
        my $i = 0;
        while ($i < 10) {
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $result = $parser->parse_string($code);
    ok $result, 'Parsed successfully';

    my $graph = $result->graph;

    # Find Loop node
    my @loop_nodes = grep { $_->op eq 'Loop' } $graph->nodes->@*;
    my $loop_id = $loop_nodes[0]->id;
    my $loop = $loop_nodes[0];

    # Find loop phi
    my @loop_phis = grep {
        $_->op eq 'Phi' &&
        $_->inputs->[0] eq $loop_id
    } $graph->nodes->@*;

    my $phi = $loop_phis[0];

    # Phi structure: [control, initial_value, loop_value]
    # The loop_value should be the updated value from within the loop
    is scalar($phi->inputs->@*), 3, 'Phi has three inputs: control, initial, loop value';

    # Loop node should have backedge
    cmp_ok scalar($loop->inputs->@*), '>=', 2, 'Loop has entry control and backedge';
};

subtest 'Conditionally modified variables still get phi nodes' => sub {
    my $code = q{
        my $count = 0;
        my $i = 0;
        while ($i < 10) {
            if ($i > 5) {
                $count = $count + 1;
            }
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $result = $parser->parse_string($code);
    ok $result, 'Parsed successfully';

    my $graph = $result->graph;

    # Find Loop node
    my @loop_nodes = grep { $_->op eq 'Loop' } $graph->nodes->@*;
    my $loop_id = $loop_nodes[0]->id;

    # Find all loop phi nodes
    my @loop_phis = grep {
        $_->op eq 'Phi' &&
        $_->inputs->[0] eq $loop_id
    } $graph->nodes->@*;

    # Both $count (conditional) and $i (unconditional) should have phis
    cmp_ok scalar(@loop_phis), '>=', 2, 'Conditionally modified variables get phi nodes';
};

