        # Create new scope level
        push $scope_stack->@*, {};
        return;
    }

    method pop_scope() {
        # Exit current scope
        my $depth = scalar($scope_stack->@*);
        if ($depth > 1) {
            pop $scope_stack->@*;
        }
        return;
    }

    method define($name, $node_id) {
        # Define a variable in the current (innermost) scope
        my $current_scope = $scope_stack->[-1];
        $current_scope->{$name} = $node_id;
        return;
    }

